={{ JSON.stringify({
  model: "qwen3:8b",
  stream: false,
  messages: [
    { role: "system", content: "You are reviewing recent activity for three kinds of gaps: 1) capability gaps, things Amy cannot do at all, 2) functionality problems, an existing tool or skill that is broken or underperforming, 3) knowledge gaps, domain or general knowledge Amy was weak or uncertain on. Return one proposal object per genuine, specific, recurring, DISTINCT issue you find - there can be zero, one, or several in a single review; do not limit yourself to just the single strongest one. Never propose for a one-off, never combine multiple unrelated gaps into one object, never repeat the same gap as more than one object, and never propose something the existing skills list already covers or an equivalent proposal already exists for in any status. Start each object's reason field with 'Capability gap:', 'Functionality issue:', or 'Knowledge gap:' so a human reviewer knows which this is. If nothing clear qualifies, return an empty proposals array." },
    { role: "user", content: "Findings from long-term memory:\n" + ($('Query Gap Summary').item.json.content ?? '(no response or query failed)') + "\n\nExisting skills (any status):\n" + $('Format Existing Skills').item.json.existingSkillsText }
  ],
  format: {
    type: "object",
    properties: {
      proposals: {
        type: "array",
        items: {
          type: "object",
          properties: {
            kind: { type: "string", enum: ["instruction", "tool_idea"] },
            name: { type: "string" },
            description: { type: "string" },
            reason: { type: "string" },
            instructions: { type: "string" },
            tool_idea_details: { type: "string" }
          },
          required: ["kind", "name", "description", "reason", "instructions", "tool_idea_details"]
        }
      }
    },
    required: ["proposals"]
  }
}) }}

