let parsed;
try {
  parsed = JSON.parse($json.message?.content ?? '{}');
} catch (e) {
  return [{ json: { shouldPropose: false } }];
}

const rawProposals = Array.isArray(parsed.proposals) ? parsed.proposals : [];

const seen = new Set();
const results = [];
for (const p of rawProposals) {
  const kebabName = (p?.name ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/-+/g, '-')
    .slice(0, 64)
    .replace(/^-|-$/g, '');

  if (!kebabName || !p?.description || !p?.reason) continue;
  if (seen.has(kebabName)) continue;
  seen.add(kebabName);

  results.push({ json: {
    shouldPropose: true,
    kind: p.kind === 'tool_idea' ? 'tool_idea' : 'instruction',
    name: kebabName,
    description: p.description,
    reason: p.reason,
    instructions: p.instructions ?? '',
    tool_idea_details: p.tool_idea_details ?? '',
  } });
}

return results.length ? results : [{ json: { shouldPropose: false } }];

parameters.jsonBody:
={{ JSON.stringify({
  model: "qwen3:8b",
  stream: false,
  messages: [
    { role: "system", content: "You are reviewing Amy's own self-representation, built by long-term memory analysis of her own messages, for personality traits or behavioral tendencies not already reflected in her current persona instructions. Propose a change only if the self-representation surfaces something clear, specific, and stable, never for a one-off or something already covered. Keep the same voice and structure as the current prompt; describe only the one additive change and why. If the self-representation is empty, vague, or already reflected, set shouldPropose to false." },
    { role: "user", content: "Amy's current persona instructions:\n" + ($('Get Current Persona').item.json.system_prompt || '(persona row not found)') + "\n\nAmy's own Honcho self-card (traits/tendencies inferred from her own behavior):\n" + (($('Get Amy Self Card').item.json.peer_card || []).join('\n') || '(no self-card yet)') }
  ],
  format: {
    type: "object",
    properties: {
      shouldPropose: { type: "boolean" },
      proposedSystemPrompt: { type: "string" },
      proposedReason: { type: "string" }
    },
    required: ["shouldPropose", "proposedSystemPrompt", "proposedReason"]
  }
}) }}

